import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/data/app.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'dev-secret-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY, title TEXT, content TEXT,
        owner TEXT, classification TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY, username TEXT UNIQUE,
        password_hash TEXT, role TEXT, department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY, action TEXT, user TEXT,
        query_text TEXT, timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        # Token format: username:hmac_signature
        parts = token.split(':')
        if len(parts) != 2:
            return jsonify({'error': 'invalid token format'}), 401
        username, sig = parts
        expected = hmac.new(SECRET_KEY.encode(), username.encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 401
        g.current_user = username
        return f(*args, **kwargs)
    return decorated

def sanitize_order(order_clause):
    """Basic sanitization - strips comments and semicolons"""
    cleaned = order_clause.replace('--', '').replace(';', '').replace('/*', '')
    return cleaned

@app.route('/api/documents/search', methods=['GET'])
@require_auth
def search_documents():
    keyword = request.args.get('q', '')
    sort_by = request.args.get('sort', 'created_at')
    direction = request.args.get('dir', 'DESC')
    dept_filter = request.args.get('dept', '')

    # Log the search for compliance
    db = get_db()
    db.execute("INSERT INTO audit_log (action, user, query_text) VALUES (?, ?, ?)",
               ('search', g.current_user, keyword))
    db.commit()

    # Build query with parameterized keyword search
    base_query = "SELECT id, title, classification, owner, created_at FROM documents WHERE content LIKE ?"
    params = ['%' + keyword + '%']

    if dept_filter:
        base_query += " AND owner IN (SELECT username FROM users WHERE department = ?)"
        params.append(dept_filter)

    # Apply sorting - sanitize_order removes obvious attacks
    sort_cleaned = sanitize_order(sort_by)
    dir_cleaned = sanitize_order(direction)

    # Construct final query with ORDER BY
    final_query = f"{base_query} ORDER BY {sort_cleaned} {dir_cleaned}"

    try:
        cursor = db.execute(final_query, params)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'search failed'}), 500

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    db = get_db()
    doc = db.execute("SELECT * FROM documents WHERE id = ?", (doc_id,)).fetchone()
    if not doc:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(doc))

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
